TLM.f("Sancti/01-06",{"officium":"In Epiphania Domini","rule":["Gloria","Credo","Prefatio=Epi"],"sections":{"Introitus":[{"k":"ref","la":"Malach 3:1; 1 Par 29:12"},{"k":"text","la":"Ecce, advénit dominátor Dóminus: et regnum in manu ejus et potéstas et impérium."},{"k":"ref","la":"Ps 71:1"},{"k":"text","la":"Deus, judícium tuum Regi da: et justítiam tuam Fílio Regis."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Ecce, advénit dominátor Dóminus: et regnum in manu ejus et potéstas et impérium."}],"Oratio":[{"k":"text","la":"Deus, qui hodiérna die Unigénitum tuum géntibus stella duce revelásti: concéde propítius; ut, qui jam te ex fide cognóvimus, usque ad contemplándam spéciem tuæ celsitúdinis perducámur."},{"k":"macro","name":"Per eumdem"}],"Lectio":[{"k":"text","la":"Léctio Isaíæ Prophétæ"},{"k":"ref","la":"Is 60:1-6"},{"k":"text","la":"Surge, illumináre, Jerúsalem: quia venit lumen tuum, et glória Dómini super te orta est. Quia ecce, ténebræ opérient terram et caligo pópulos: super te autem oriétur Dóminus, et glória ejus in te vidébitur. Et ambulábunt gentes in lúmine tuo, et reges in splendóre ortus tui. Leva in circúitu óculos tuos, et vide: omnes isti congregáti sunt, venérunt tibi: fílii tui de longe vénient, et fíliæ tuæ de látere surgent. Tunc vidébis et áfflues, mirábitur et dilatábitur cor tuum, quando convérsa fúerit ad te multitúdo maris, fortitúdo géntium vénerit tibi. Inundátio camelórum opériet te dromedárii Mádian et Epha: omnes de Saba vénient, aurum et thus deferéntes, et laudem Dómino annuntiántes."}],"Graduale":[{"k":"ref","la":"Isa 60:6; 60:1"},{"k":"text","la":"Omnes de Saba vénient, aurum et thus deferéntes, et laudem Dómino annuntiántes."},{"k":"text","la":"Surge et illumináre, Jerúsalem: quia glória Dómini super te orta est. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Matt 2:2"},{"k":"text","la":"Vídimus stellam ejus in Oriénte, et vénimus cum munéribus adoráre Dóminum. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 2:1-12"},{"k":"text","la":"Cum natus esset Jesus in Béthlehem Juda in diébus Heródis regis, ecce, Magi ab Oriénte venerunt Jerosólymam, dicéntes: Ubi est, qui natus est rex Judæórum? Vidimus enim stellam ejus in Oriénte, et vénimus adoráre eum. Audiens autem Heródes rex, turbatus est, et omnis Jerosólyma cum illo. Et cóngregans omnes principes sacerdotum et scribas pópuli, sciscitabátur ab eis, ubi Christus nasceretur. At illi dixérunt ei: In Béthlehem Judæ: sic enim scriptum est per Prophétam: Et tu, Béthlehem terra Juda, nequaquam mínima es in princípibus Juda; ex te enim éxiet dux, qui regat pópulum meum Israël. Tunc Heródes, clam vocátis Magis, diligénter dídicit ab eis tempus stellæ, quæ appáruit eis: et mittens illos in Béthlehem, dixit: Ite, et interrogáte diligénter de púero: et cum invenéritis, renuntiáte mihi, ut et ego véniens adórem eum. Qui cum audíssent regem, abiérunt. Et ecce, stella, quam víderant in Oriénte, antecedébat eos, usque dum véniens staret supra, ubi erat Puer. Vidéntes autem stellam, gavísi sunt gáudio magno valde. Et intrántes domum, invenérunt Púerum cum María Matre ejus, (hic genuflectitur) et procidéntes adoravérunt eum. Et, apértis thesáuris suis, obtulérunt ei múnera, aurum, thus et myrrham. Et respónso accépto in somnis, ne redírent ad Heródem, per aliam viam revérsi sunt in regiónem suam."}],"Offertorium":[{"k":"ref","la":"Ps 71:10-11"},{"k":"text","la":"Reges Tharsis, et ínsulæ múnera ófferent: reges Arabum et Saba dona addúcent: et adorábunt eum omnes reges terræ, omnes gentes sérvient ei."}],"Secreta":[{"k":"text","la":"Ecclésiæ tuæ, quǽsumus, Dómine, dona propítius intuere: quibus non jam aurum, thus et myrrha profertur; sed quod eisdem munéribus declarátur, immolátur et súmitur, Jesus Christus, fílius tuus, Dóminus noster:"},{"k":"macro","name":"Qui tecum"}],"Communio":[{"k":"ref","la":"Matt 2:2"},{"k":"text","la":"Vídimus stellam ejus in Oriénte, et vénimus cum munéribus adoráre Dóminum."}],"Postcommunio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, quæ sollémni celebrámus officio, purificátæ mentis intellegéntia consequámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"51851082a1fc32e2":{"t":"Mal 3, 1, 1 Ljet 29, 12, Ps 71, 1\n(Mal 3, 1, 1 Ljet 29, 12) Evo, došao je vladar Gospodin. U njegovoj je ruci kraljevstvo i moć i vlast. (Ps 71, 1) Bože, daj Kralju svoju sudačku vlast i svoju pravdu Kraljevu Sinu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Mal 3, 1, 1 Ljet 29, 12) Evo, došao je vladar Gospodin. U njegovoj je ruci kraljevstvo i moć i vlast."},"765691e1e2dea9f9":{"t":"<i>Pomolimo se</i>.\nBože, koji si na današnji dan Jedinorođenoga Sina svoga objavio narodima po zvijezdi prethodnici, podaj milostivo, da mi koji smo te već upoznali po vjeri budemo privedeni do gledanja tvoje uzvišene krasote.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"23852547fbfa640a":{"t":"Iz 60, 1-6\nČitanje Izaije Proroka: Ustani, rasvijetli se, Jeruzaleme, jer je došlo tvoje svjetlo i obasjala te Gospodnja slava. Gle, zemlju će pokriti tama i narode će obaviti mrak, a nad tobom će zasjati Gospodin i na tebi će se vidjeti njegova slava. Narodi će hodati u tvojem svjetlu i kraljevi u sjaju tvoga dolaska. – Podigni svoje oči i gledaj: Svi su se ovi skupili, dolaze k tebi. Tvoji će sinovi doći izdaleka i tvoje kćeri ustat će sa svih strana. Ti ćeš to vidjeti i napunit ćeš se miline, divit će se i širiti tvoje srce, kad se mnoštvo s mora obrati prema tebi i kad silan narod dođe k tebi. Pokrit će te mnoštvo deva, dromedari iz Madijana i Efe. Svi će iz Sabe doći noseći zlato i tamjan i navješćujući Gospodnju slavu."},"1e556b082189917a":{"t":"Iz 60, 6 i 1\nSvi će iz Sabe doći noseći zlato i tamjan i navješćujući Gospodnju slavu. Ustani, rasvijetli se, Jeruzaleme, jer te obasjala Gospodnja slava.\n\nMt 2, 2\n<i>Aleluja</i>, <i>aleluja</i>.\nVidjeli smo njegovu zvijezdu na istoku i dođosmo s darovima da se poklonimo Gospodinu. <i>Aleluja</i>."},"bca9269e2481bf32":{"t":"Mt 2, 1-12\nSlijedi sveto Evanđelje po Mateju. Kad se Isus rodio u Betlehemu u Judeji za Herodova vladanja, dođu mudraci s istoka u Jeruzalem i upitaju: »Gdje je židovski kralj koji se rodio? Vidjeli smo naime njegovu zvijezdu na istoku i dođosmo da mu se poklonimo.« – Kad je kralj Herod to čuo, uznemiri se, a s njim i sav Jeruzalem. I sazove sve svećeničke poglavare i narodne pismoznance, te ih pitaše gdje Krist treba da se rodi. Oni mu odgovore: »U Betlehemu u Judeji, jer je ovako napisao prorok: I ti, Betleheme, Judina zemljo, nipošto nisi najmanji među glavnim judejskim gradovima, jer će iz tebe izići vođa koji će vladati nad mojim narodom Izraelom.« – Tada Herod potajno pozove mudrace i pomnjivo ih ispita o vremenu kada im se pojavila zvijezda. I šaljući ih u Betlehem reče im: »Pođite i raspitajte se točno za Dijete. Kad ga nađete, javite mi da i ja pođem te mu se poklonim.« – Kad su oni čuli kralja, otiđoše. I gle, zvijezda koju su vidjeli na istoku, išla je pred njima sve dok se na svom putu ne zaustavi nad mjestom gdje je bilo Dijete. I kad ugledaše zvijezdu, vrlo se obradovaše. Uđu u kuću, nađu Dijete s njegovom majkom Marijom, [OVDJE SE POKLEKNE] padnu ničice te mu se poklone. I otvore svoje blago i dadu mu darove: zlato, tamjan i miru. I opomenuti u snu da se ne vraćaju k Herodu, vrate se drugim putem u svoju zemlju."},"3fc236c7f2696475":{"t":"Ps 71, 10-11\nKraljevi Tarzisa i otoka prinijet će poklone. Kraljevi Arabije i Sabe donijet će darove. Poklonit će mu se svi zemaljski kraljevi, služit će mu svi narodi."},"a1992f2804e5386e":{"t":"Milostivo pogledaj, molimo, Gospodine, darove svoje Crkve kojima ti se više ne prikazuje zlato, tamjan i mira, nego ono što se tim darovima označuje, to se žrtvuje i blaguje: Isus Krist, tvoj Sin, naš Gospodin:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"93e8203b4ea3a0a5":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože: – jer kad se tvoj Jedinorođenac pojavio u našem smrtnom tijelu, on nas je novim svjetlom svoje besmrtnosti obnovio. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"a30154876acf1133":{"t":"Mt 2, 2\nVidjeli smo njegovu zvijezdu na istoku i dođosmo s darovima da se poklonimo Gospodinu."},"733012d1d7688ca9":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da ono što svečanom službom slavimo, razumom očišćene duše i shvatimo.\n<i>Per Dóminum nostrum Iesum Christum, Fílium tuum: Qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus: per ómnia saecula saéculórum</i>."}}});
